// Generated by tools/build-sw.mjs — do not edit sw.js by hand; edit sw.template.js.
const VERSION = '__VERSION__';
const CACHE = `chematrix-${VERSION}`;
const PRECACHE = __FILES__;

self.addEventListener('install', (event) => {
  // cache.addAll is atomic: if any file fails to download, nothing is stored and
  // the previous version stays in control, so an interrupted update cannot break the app.
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })))));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('chematrix-') && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // the app never needs other origins
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // app shell: every navigation is answered by the cached index.html (hash routing)
    if (req.mode === 'navigate') {
      const shell = await cache.match('./index.html');
      if (shell) return shell;
      try { return await fetch(req); } catch { return new Response('<h1>CHEMATRIX</h1><p>Offline and not yet installed. Open the app once while online.</p>', { headers: { 'Content-Type': 'text/html; charset=utf-8' }, status: 503 }); }
    }
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit; // cache-first: no network request while offline
    try {
      return await fetch(req);
    } catch {
      return new Response('', { status: 504, statusText: 'Offline' });
    }
  })());
});
